from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext, getcontext

_CENT = Decimal("0.01")


def _parse(value):
    if not isinstance(value, str):
        raise ValueError("input must be a string")
    try:
        number = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid decimal: {value!r}") from None
    if not number.is_finite():
        raise ValueError("input must be finite")
    return number


def _required_prec(*decimals):
    # Enough precision to represent exact intermediate results plus margin for
    # correct rounding to 2 decimal places. Sum of significant digits plus
    # scale plus safety margin.
    total_digits = 0
    max_scale = 0
    for d in decimals:
        tup = d.as_tuple()
        # len 1 for zero as well
        digits = len(tup.digits)
        total_digits += digits
        if tup.exponent < 0:
            max_scale = max(max_scale, -tup.exponent)
        elif tup.exponent > 0:
            # large exponent also contributes to needed precision when aligning
            max_scale = max(max_scale, tup.exponent)
    # Need at least total digits + scale + extra for division rounding
    needed = total_digits + max_scale + 10
    # Ensure at least default 28 and some headroom for small numbers
    return max(needed, 28, 50)


def percent_change(old: str, new: str) -> Decimal | None:
    old_d, new_d = _parse(old), _parse(new)
    if old_d == 0:
        return Decimal("0.00") if new_d == 0 else None
    prec = _required_prec(old_d, new_d)
    with localcontext() as ctx:
        ctx.prec = prec
        ctx.rounding = ROUND_HALF_UP
        change = (new_d - old_d) / abs(old_d) * Decimal(100)
        return change.quantize(_CENT, rounding=ROUND_HALF_UP)


def apply_percent_change(old: str, percent: str) -> Decimal:
    old_d, pct = _parse(old), _parse(percent)
    prec = _required_prec(old_d, pct)
    with localcontext() as ctx:
        ctx.prec = prec
        ctx.rounding = ROUND_HALF_UP
        result = old_d * (Decimal(1) + pct / Decimal(100))
        return result.quantize(_CENT, rounding=ROUND_HALF_UP)
